using namespace std;
const int N = 5005;
int t, n, mod, f[N][N], ans;
inline void add(int& x, int y){x += y;if (x >= mod) x -= mod;}
int main(){scanf("%d", &t);
	while (t --){scanf("%d%d", &n, &mod), f[0][0] = 1, ans = 0;
		for (int i = 1;i <= n;i ++) for (int j = 0;j <= i;j ++) f[i][j] = 0;
		for (int i = 1;i <= n;i ++)
		for (int j = 0, now;j < i;j ++)
		if (now = f[i - 1][j]) add(f[i][j + 1], now),
		f[i][j] = (f[i][j] + (n - i + 1ll) * (j + 1) * now) % mod;
		for (int j = 0;j <= n;j ++) add(ans, f[n][j]);printf("%d\n", ans);
	}
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
struct stu{
	int x;
	ll dp;
};
int n,a[100007],b[100007];
vector<stu> f,g;
const ll inf=0x3f3f3f3f3f3f3f3f;
void Subt(){
	cin>>n;
	for(int i=1;i<n;i++) cin>>a[i];
	for(int i=1;i<=n;i++) cin>>b[i];
	a[n]=0;
	f.clear();
	f.push_back((stu){0,0});
	for(int i=1;i<=n;i++){
		int x=0;
		g.clear();
		for(int j=30;j>=-1;j--){
			int y=x|a[i-1]|a[i];
			if(j!=-1) y|=(1<<j); 
			if(y>=b[i]){
				ll mn=inf;
				for(stu l:f){
					if((l.x&y)!=a[i-1]) continue;
					mn=min(mn,l.dp+y-b[i]);
				}
				if(mn<inf) g.push_back((stu){y,mn});
			}
			x|=((1<<j)&b[i]);
		}
		swap(f,g);
	}
	ll mn=inf;
	for(stu l:f) mn=min(mn,l.dp);
	if(mn<inf) cout<<mn<<endl;
	else cout<<-1<<endl;
	return;
}
signed main(){
	ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
	int T=1;
	cin>>T;
	while(T--) Subt();
}

#include<iostream>
#include<cstdio>
#include<algorithm>
#include<cstring>
